from native_lib import *
import struct

slides=[]; image_parts={}
def new(title,footer,notes_text):
    s=Slide(len(slides)+1,title); slides.append(s); s.footer(footer); s.notes=notes_text; return s
def picture(s,source,x,y,w,h):
    data=(ROOT/source).read_bytes(); iw,ih=struct.unpack('>II',data[16:24]); scale=min(w/iw,h/ih); ww,hh=iw*scale,ih*scale
    pic=sub(s.tree,P,'pic'); nv=sub(pic,P,'nvPicPr'); sub(nv,P,'cNvPr',{'id':str(s.next),'name':source}); s.next+=1; sub(nv,P,'cNvPicPr'); sub(nv,P,'nvPr')
    rid=f'rIdImage{s.next}'; bf=sub(pic,P,'blipFill'); sub(bf,A,'blip',{q(R,'embed'):rid}); sub(sub(bf,A,'stretch'),A,'fillRect')
    sp=sub(pic,P,'spPr'); xf(sp,x+(w-ww)/2,y+(h-hh)/2,ww,hh); sub(sub(sp,A,'prstGeom',{'prst':'rect'}),A,'avLst')
    name=f'image_{s.num}_{s.next}.png'; image_parts['ppt/media/'+name]=data; s.rels.append((rid,R+'/image','../media/'+name))

