with zipfile.ZipFile(ROOT/'requirements/Шаблон презентации.pptx') as z: parts={n:z.read(n) for n in z.namelist()}
types=E.fromstring(parts['[Content_Types].xml'])
def addtype(name,content):
    if not any(el.get('PartName')==name for el in types): E.SubElement(types,q(CT,'Override'),{'PartName':name,'ContentType':content})
pres=E.fromstring(parts['ppt/presentation.xml']); ids=pres.find(q(P,'sldIdLst')); ids.clear()
pr=E.fromstring(parts['ppt/_rels/presentation.xml.rels'])
for e in list(pr):
    if e.get('Type','').endswith('/slide'): pr.remove(e)
for s in slides:
    rid=f'rIdSlide{s.num}'; sub(ids,P,'sldId',{'id':str(255+s.num),q(R,'id'):rid}); E.SubElement(pr,q(REL,'Relationship'),{'Id':rid,'Type':R+'/slide','Target':f'slides/slide{s.num}.xml'})
    parts[f'ppt/slides/slide{s.num}.xml']=xml(s.root)
    parts[f'ppt/slides/_rels/slide{s.num}.xml.rels']=relationships([('rIdLayout',R+'/slideLayout','../slideLayouts/slideLayout1.xml'),('rIdNotes',R+'/notesSlide',f'../notesSlides/notesSlide{s.num}.xml')]+s.rels)
    parts[f'ppt/notesSlides/notesSlide{s.num}.xml']=xml(notes(s.notes))
    parts[f'ppt/notesSlides/_rels/notesSlide{s.num}.xml.rels']=relationships([('rIdSlide',R+'/slide',f'../slides/slide{s.num}.xml')])
    addtype(f'/ppt/slides/slide{s.num}.xml','application/vnd.openxmlformats-officedocument.presentationml.slide+xml')
    addtype(f'/ppt/notesSlides/notesSlide{s.num}.xml','application/vnd.openxmlformats-officedocument.presentationml.notesSlide+xml')
parts['ppt/presentation.xml']=xml(pres); E.register_namespace('',REL); parts['ppt/_rels/presentation.xml.rels']=xml(pr)
parts.update(image_parts); E.register_namespace('',CT); parts['[Content_Types].xml']=xml(types)
out=NIGHT/'output/Dota2_All_Cases_v2.pptx'
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:
    for n,v in parts.items(): z.writestr(n,v)
(NIGHT/'output/Текст_защиты.md').write_text('# Пояснения к защите всех трёх кейсов\n\n'+'\n\n'.join(f'## {s.num}. {s.title}\n\n{s.notes}' for s in slides),encoding='utf-8')
(NIGHT/'build/slide_manifest.json').write_text(json.dumps([{'slide':s.num,'title':s.title,'notes':s.notes} for s in slides],ensure_ascii=False,indent=2),encoding='utf-8')
print(out)
